#include<bits/stdc++.h>
using namespace std;
int main ()
{
    int t ;
    cin >> t ;
    string s ;
    cin >> s ;

    //ab =1,ac=2 .....
    //ba=26 , bc=27 , .........

    //the idea is to find the position of the first character and the second character in the string and then calculate the distance between them in terms of their positions in the alphabet.
    // in coding terms, we can use the ASCII values of the characters to find their positions in the alphabet. The position of a character 'c' can be found using the formula: position = c - 'a' + 1 for lowercase letters.


    int ans = 0 ;
    for (int i = 0 ; i < t-1 ; i++)
    {
        ans += abs(s[i+1] - s[i]) ;
        cout << ans << endl ;
    }
    
}
